import{d as r,C as a,o as g,c as d,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第四十章","description":"《正易心法》第四十章——名易之义，非训变易：《易》者大易，「未见气」，希微玄虚凝寂；易变而为一，清轻为天、重浊为地、冲和为人；学者作「变易」之解是字言之，非宗旨之学。","frontmatter":{"title":"正易心法·第四十章","description":"《正易心法》第四十章——名易之义，非训变易：《易》者大易，「未见气」，希微玄虚凝寂；易变而为一，清轻为天、重浊为地、冲和为人；学者作「变易」之解是字言之，非宗旨之学。","category":"guide","aliases":["正易心法第四十章","名易之义非训变易","大易与变易"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-40.md","filePath":"yijing/zheng-yi-xin-fa/chapter-40.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-40.md"},x=r({...c,setup(u){const i=[{id:"z40-01",label:"一、非训变易",showLabel:!0,sentences:[["名易之义，非训",{text:"变易",glossary:"bianyi"},"。阴阳根本，有在于是。"]],note:["「易」这个名字的含义，不是训为「变易」。阴阳的根本，就在这里。（**这是《正易心法》中最重要的理论章之一**：前面讲象、讲数、讲筮，**本章追问的是最根本的一问——「易」到底是什么？** 如果连「易」是什么都没搞清楚，所有的象数推演都是空中楼阁。）"]},{id:"z40-02",label:"二、大易未见气",showLabel:!0,sentences:[["《易》者，",{text:"大易",glossary:"dayi"},"也。大易，",{text:"未见气",glossary:"weijianqi"},"也。视之不见，听之不闻，循之不得，故曰《易》。《易》者，",{text:"希微玄虚凝寂",glossary:"xiweiXuanxu"},"之称也。"]],note:["《易》是「大易」；大易，是气尚未出现的状态。看它看不见，听它听不见，摸它摸不着，所以叫做《易》。《易》，是希、微、玄、虚、凝、寂这些词的总称。（**「未见气」三个字要读准**：不是「没有气」，是**「气这个概念都还没有」**——**比「无极」更早，是「无」之前的「无」。** 而「视之不见、听之不闻、循之不得」三句，**几乎直接取自《老子》十四章**（「视之不见名曰夷，听之不闻名曰希，搏之不得名曰微」）——**麻衣只是把「夷希微」换成了「大易」。**）"]},{id:"z40-03",label:"三、易变而为一",showLabel:!0,sentences:[["及易变而为一，一变而为七，七变而为九，九复变而为一也。一者，",{text:"形变之始",glossary:"xingbianZhishi"},"也。清轻者上为天，重浊者下为地，",{text:"冲和气",glossary:"chongheqi"},"者中为人。"]],note:["等到易变化而产生一，一变而到达七，七变而到达九，九再变化回到一。一，是有形变化的起点。清轻之气上升为天，重浊之气下沉为地，冲和之气居中为人。（**三才的生成**：**天与地是气的两个极端**（清轻／重浊），**人是「冲和」的中间状态**——**既不像天那样纯阳，也不像地那样纯阴。** 这正是《老子》「冲气以为和」的落处：**人不是天地的产物，而是与天地同源的第三种气。**）"]},{id:"z40-04",label:"四、本于冲虚",showLabel:!0,sentences:[["谓之《易》者，知阴阳之根本有在于是也。此说本于《",{text:"冲虚真经",glossary:"chongxuZhenjing"},"》，是为定论。"]],note:["之所以称之为《易》，是因为知道阴阳的根本就在这里。这个说法本于《冲虚真经》（《列子》），是定论。（**麻衣的判断很坚决：「是为定论」**——他把《列子》的宇宙论当作**权威依据**。**一个为《易》作注的人，用道家的书来定《易》之名**——这本身就是陈抟一脉「以道解易」的明证。）"]},{id:"z40-05",label:"五、学者盲然不悟",showLabel:!0,sentences:[["学者盲然不悟，乃作变易之易，即是字言之，非",{text:"宗旨之学",glossary:"zongzhiZhixue"},"也。"]],note:["学者茫然不能领悟，把《易》训为「变易」之易——这只是从字面上说，不是把握宗旨的学问。（**麻衣的批评很尖锐**：**如果易＝变化，那《易》就是一本「关于变化的书」，一个用来分析变化的工具。** 但**「变易」说的是「易在变化之中」（工具），麻衣说的是「易在变化之前」（根源）**——**就像水流与水源：研究水流是「变易之学」，追问水源是「大易之学」。**）"]},{id:"z40-06",label:"六、扬雄与日月",showLabel:!0,sentences:[["唯",{text:"扬雄",glossary:"yangxiong"},"为书，拟之曰：《",{text:"太玄",glossary:"taixuan"},"》，颇得之。道家亦以",{text:"日月为易",glossary:"riyueWeiyi"},"，盖其本阴阳而言也。"]],note:["只有扬雄著书，仿《易》命名为《太玄》，颇为得到了真义；道家也用日月来解释「易」字的古字形，这是从阴阳的根本来说的。（**为什么扬雄「颇得之」？** 因为他不把「易」训为「变易」，而直接命名为「**太玄**」——**太＝大，玄＝深远不可见**，与麻衣说的「大易」高度吻合。**但麻衣用「颇」字：得了方向，未全得其本**（《太玄》毕竟是仿作）。**「日月为易」则是「得其象」**：日月已是分化之后的阴阳，而大易是阴阳**之前**——**容器 vs 根源，这是本章最要紧的分辨。**）"]}],p=[{id:"bianyi",term:"变易",pinyin:"biàn yì",meaning:"把「易」训为「变化」。麻衣判为「字言之」，非宗旨之学。"},{id:"dayi",term:"大易",pinyin:"dà yì",meaning:"最根本的易。「未见气」之前的状态，比太极更早。"},{id:"weijianqi",term:"未见气",pinyin:"wèi jiàn qì",meaning:"气尚未出现。比「无极」更彻底的「无」。"},{id:"xiweiXuanxu",term:"希微玄虚凝寂",pinyin:"xī wēi xuán xū",meaning:"五个形容词叠加：希（稀少）、微（细小）、玄（深远）、虚（空无）、凝寂（凝固寂静）。"},{id:"xingbianZhishi",term:"形变之始",pinyin:"xíng biàn zhī shǐ",meaning:"有形变化的起点。一是从无形到有形的第一步。"},{id:"chongheqi",term:"冲和气",pinyin:"chōng hé qì",meaning:"冲和之气。冲＝冲虚，和＝和谐。不轻不重的中间之气，即人的本原。"},{id:"chongxuZhenjing",term:"冲虚真经",pinyin:"chōng xū zhēn jīng",meaning:"《列子》的道教尊称。麻衣以之为「定论」的依据。"},{id:"zongzhiZhixue",term:"宗旨之学",pinyin:"zōng zhǐ zhī xué",meaning:"把握根本宗旨的学问。麻衣认为这才是真正的易学。"},{id:"yangxiong",term:"扬雄",pinyin:"yáng xióng",meaning:"西汉文学家、哲学家（前 53—18），著《太玄经》，仿《易》而作。"},{id:"taixuan",term:"太玄",pinyin:"tài xuán",meaning:"扬雄所著。太＝大，玄＝黑暗深远不可见——与麻衣说的「大易」高度吻合。"},{id:"riyueWeiyi",term:"日月为易",pinyin:"rì yuè wéi yì",meaning:"道家的字形解说：易＝日（阳）＋月（阴）。麻衣评为「本阴阳而言」，方向对但只得其象。"}];return(b,n)=>{const o=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",24)),e(o,{colophon:"非训变易 · 大易未见气 · 一者形变之始 · 宗旨之学",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十章原文",sections:i,glossary:p}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文「所之不闻」当为「听之不闻」之讹，此处随底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"大易",pinyin:["dà","yì"],meaning:"《易》的根本含义：气尚未出现之前的状态——比太极更早，是「无」之前的「无」。"},{term:"希微玄虚凝寂",pinyin:["xī","wēi"],meaning:"大易的六个特征：希、微、玄、虚、凝寂——皆不可见不可闻之貌。"},{term:"非训变易",pinyin:["biàn","yì"],meaning:"「易」不是「变化」之意。变易说的是「易在变化之中」，麻衣说的是「易在变化之前」。"},{term:"一者形变之始",pinyin:["xíng","biàn"],meaning:"一是从无形到有形的第一步。清轻为天、重浊为地、冲和为人，三才由此而立。"},{term:"日月为易",pinyin:["rì","yuè"],meaning:"道家字形说：易＝日＋月。麻衣评为「本阴阳而言」——得其象，未得其本。"}]}),n[3]||(n[3]=t("",24))])}}});export{m as __pageData,x as default};
